(* [comment removed for export] *)
Definition csc_contract_t : Prop :=
  forall (fr : bvmap 5 word) (cs : bv 32) C Ar A m md regs (s pix1 hs vs w h cm datas : Z) (cv : cmapv) (ret : word) (S : TSet),
  Cok C -> MBC C -> W C A m md -> sub_live Ar A -> frm_zero cs ->
  getr regs 2 = Z_to_bv 64 s -> (s mod 16 = 0)%Z -> (c_top C - LSTK + CSC_STACK <= s)%Z -> (s <= c_top C)%Z ->
  getr regs 1 = ret -> ret_ok ret -> getr regs 4 = Z_to_bv 64 0x1381d0 ->
  getr regs 10 = Z_to_bv 64 pix1 -> getr regs 11 = Z_to_bv 64 pix1 -> getr regs 12 = Z_to_bv 64 hs -> getr regs 13 = Z_to_bv 64 vs ->
  ((hs = 1 /\ vs = 8) \/ (hs = 30 /\ vs = 1))%Z ->
  pix1_at C Ar A m pix1 w h cm datas cv -> pix1 <> datas -> hdr_ok w h 1 -> (1 <= w)%Z -> (1 <= h)%Z ->
  forall (kR bR : Z), aroom A (m_vmmaps md) kR bR -> (RK_csc vs <= kR)%Z -> (RB_csc vs w h cm <= bR)%Z ->
  (forall (fr' : bvmap 5 word) (cs' : bv 32) A' m' vm' regs' (cm' : Z) (cv' : cmapv),
     frm_zero cs' -> (forall r : reg, In (u r) fs_list -> reg_get fr' r = reg_get fr r) ->
     W C A' m' (with_vmmaps vm' md) -> cs_kept regs regs' -> getr regs' 10 = Z_to_bv 64 pix1 ->
     sub_live Ar A' -> POSTM C Ar s m m' ->
     pix1_at C Ar A' m' pix1 w h cm' datas cv' -> csc_live A A' cm cv cm' cv' -> (cm <> 0%Z -> csc_keep A A' cm cv) ->
     aroom A' vm' (kR - RK_csc vs) (bR - RB_csc vs w h cm) ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr cs) regs (0xa4878 : word) m al_rom) md) S.

Lemma csc_contract_of : pixCloseSafeCompBrick_inplace_contract -> csc_contract_t.
Proof.
  intros HIN. unfold csc_contract_t.
  intros fr cs C Ar A m md regs s pix1 hs vs w h cm datas cv ret S
    CK MB HW SUB FZ H2 Hs16 Hlo Hhi H1 Hret H4 H10 H11 H12 H13 Hhv P1 NE HD Hw Hh kR bR RM HkR HbR HC.
  apply (HIN fr cs C Ar A m md regs s pix1 hs vs w h cm datas cv ret S CK MB HW SUB FZ H2 Hs16 Hlo Hhi H1 Hret H4
           H10 H11 H12 H13 Hhv P1 NE HD Hw Hh kR bR RM HkR HbR).
  unfold csc_K. intros fr' cs' A' m' vm' regs' cm' cv' FZ' FSK HW' CS A10 SUB' PM P1' CSL RM'.
  exact (HC fr' cs' A' m' vm' regs' cm' cv' FZ' FSK HW' CS A10 SUB' PM P1' CSL (csc_keep_of A A' cm cv cm' cv' CSL) RM').
Qed.

